
create schema if not exists private;
create or replace function public.financial_core_can(p_org uuid,p_scope text) returns boolean language sql stable security definer set search_path='pg_catalog','public' as $$select public.effective_organization_permission(p_org,p_scope,null,null);$$;
create or replace function public.can_self_approve_financial_event(p_org uuid) returns boolean language plpgsql stable security definer set search_path='pg_catalog','public' as $$declare v_role text;v_policy text;begin if auth.uid() is null then return false;end if;select m.role,o.approval_policy into v_role,v_policy from public.organization_members m join public.organizations o on o.id=m.organization_id where m.organization_id=p_org and m.user_id=auth.uid() and m.status='ACTIVE';if v_role is null or v_policy='STRICT_SEGREGATION' then return false;end if;if v_policy='OWNER_CONTROLLED' then return v_role='OWNER';end if;if v_policy='ROLE_BASED' then return public.explicit_organization_permission(p_org,'financial_core.self_approve',null,null);end if;return false;end$$;
create or replace function public.financial_event_has_valid_approval(p_event_id uuid) returns boolean language plpgsql stable security definer set search_path='pg_catalog','public' as $$declare e public.financial_events%rowtype;pol text;begin select * into e from public.financial_events where id=p_event_id;if e.id is null then return false;end if;select approval_policy into pol from public.organizations where id=e.organization_id;if exists(select 1 from public.financial_event_approvals a where a.event_id=e.id and a.organization_id=e.organization_id and a.decision='APPROVED' and a.approver_id<>e.created_by) then return true;end if;if pol='OWNER_CONTROLLED' and exists(select 1 from public.financial_event_approvals a join public.organization_members m on m.organization_id=a.organization_id and m.user_id=a.approver_id and m.status='ACTIVE' where a.event_id=e.id and a.decision='APPROVED' and a.approver_id=e.created_by and m.role='OWNER') then return true;end if;if pol='ROLE_BASED' and exists(select 1 from public.financial_event_approvals a where a.event_id=e.id and a.approver_id=e.created_by and a.decision='APPROVED' and public.explicit_organization_permission(e.organization_id,'financial_core.self_approve',a.approver_id,null)) then return true;end if;return false;end$$;
create or replace function public.transition_financial_event(p_event_id uuid,p_new_status text,p_note text default null) returns text language plpgsql security definer set search_path='pg_catalog','public' as $$declare e public.financial_events%rowtype;scope text;valid boolean:=false;begin select * into e from public.financial_events where id=p_event_id for update;if e.id is null then raise exception 'FINANCIAL_EVENT_NOT_FOUND';end if;if (e.status='DRAFT' and p_new_status in('PLANNED','CANCELLED')) or(e.status='PLANNED' and p_new_status in('COMMITTED','CANCELLED')) or(e.status='COMMITTED' and p_new_status in('ACTUAL','CANCELLED')) or(e.status='ACTUAL' and p_new_status='REVERSED') then valid:=true;end if;if not valid then raise exception 'INVALID_FINANCIAL_EVENT_TRANSITION:%->%',e.status,p_new_status;end if;scope:=case when p_new_status='ACTUAL' then case when e.event_type='REVERSAL' then 'financial_core.reverse' else 'financial_core.post' end when p_new_status='REVERSED' then 'financial_core.reverse' else 'financial_core.create' end;if not public.financial_core_can(e.organization_id,scope) then raise exception 'FINANCIAL_CORE_TRANSITION_DENIED';end if;if p_new_status='ACTUAL' and not public.financial_event_has_valid_approval(e.id) then raise exception 'VALID_APPROVAL_REQUIRED';end if;update public.financial_events set status=p_new_status,updated_at=now(),posted_by=case when p_new_status='ACTUAL' then auth.uid() else posted_by end,posted_at=case when p_new_status='ACTUAL' then now() else posted_at end where id=e.id;insert into public.financial_event_status_history(event_id,organization_id,from_status,to_status,actor_id,note) values(e.id,e.organization_id,e.status,p_new_status,auth.uid(),p_note);return p_new_status;end$$;
create or replace function public.approve_financial_event(p_event_id uuid,p_note text default null) returns bigint language plpgsql security definer set search_path='pg_catalog','public' as $$declare e public.financial_events%rowtype;rid bigint;begin select * into e from public.financial_events where id=p_event_id for update;if e.id is null then raise exception 'FINANCIAL_EVENT_NOT_FOUND';end if;if not public.financial_core_can(e.organization_id,'financial_core.approve') then raise exception 'FINANCIAL_CORE_APPROVE_DENIED';end if;if e.status<>'COMMITTED' then raise exception 'EVENT_MUST_BE_COMMITTED_BEFORE_APPROVAL';end if;if e.created_by=auth.uid() and not public.can_self_approve_financial_event(e.organization_id) then raise exception 'CREATOR_CANNOT_APPROVE_OWN_EVENT';end if;insert into public.financial_event_approvals(event_id,organization_id,approver_id,decision,note) values(e.id,e.organization_id,auth.uid(),'APPROVED',p_note) returning id into rid;return rid;end$$;
grant execute on function public.financial_core_can(uuid,text),public.can_self_approve_financial_event(uuid),public.financial_event_has_valid_approval(uuid),public.transition_financial_event(uuid,text,text),public.approve_financial_event(uuid,text) to authenticated;
